from pathlib import Path
import os,json,collections,shutil,sys,time
R=Path.cwd();sys.path.insert(0,str(R/'scripts'))
from phase_admission_protocol import read,ref,owner_live
T=R/'.cache/v189-completed-browser-storage-v1';assert not T.exists();T.mkdir()
groups=collections.defaultdict(list);proofs=[];owners={}
for p in (R/'docs/results').glob('*native-viewer-verification-v1.json'):
 d=read(p);bound=[]
 for b in d.get('screenshot_bindings',[]):
  f=Path(b['path'])
  if not f.is_relative_to(R/'.cache/quality-20261107'):continue
  root=R/'.cache/quality-20261107'/f.relative_to(R/'.cache/quality-20261107').parts[0]
  if root.name.startswith('V189'):continue
  for launch in root.glob('*launch-v1.json'):
   o=read(launch).get('owner')
   if o:assert not owner_live(o);owners[str(launch)]=o
  assert ref(f)==b and not f.is_symlink();groups[b['sha256']].append(b);bound.append(b)
 if bound:proofs.append({'proof':ref(p),'screenshots':bound})
operations=[];logical=0
for digest,bindings in groups.items():
 bindings=sorted(bindings,key=lambda b:b['path']);canon=Path(bindings[0]['path']);seen={}
 for b in bindings:
  f=Path(b['path']);s=f.stat();seen[s.st_dev,s.st_ino]=s.st_blocks*512
  if (s.st_dev,s.st_ino)!=(canon.stat().st_dev,canon.stat().st_ino):operations.append({'canonical':ref(canon),'destination':b,'device':s.st_dev})
 if len(seen)>1:logical+=sum(seen.values())-canon.stat().st_blocks*512
plan={'status':'planned-byte-identical-terminal-browser-screenshot-hardlinks','created_unix_UTC':time.time(),'source':dict(ref(__file__),text=Path(__file__).read_text()),'proofs':proofs,'terminal_owners':owners,'operations':operations,'logical_unique_allocated_reduction_bytes':logical,'free_before':shutil.disk_usage(R).free,'scope':'Only byte-identical local screenshot PNGs in six completed trials. Preserve every path/hash/browserproof byte; hardlink shared contents atomically. All36original launchowners terminal; no V189 live path orsource/model/capture/checkpoint/receipt is replaced. External storage unchanged. Shared filesystemfree delta is not attributed solely to this operation.'}
with (T/'plan-v1.json').open('x') as f:json.dump(plan,f,indent=2);f.write('\n')
for path,o in owners.items():assert not owner_live(o)
for n,op in enumerate(operations):
 a,b=Path(op['canonical']['path']),Path(op['destination']['path']);assert ref(a)==op['canonical'] and ref(b)==op['destination']
 tmp=b.with_name(b.name+'.v189-link-tmp');assert not tmp.exists();os.link(a,tmp);os.replace(tmp,b)
 assert ref(b)==op['destination'] and a.stat().st_ino==b.stat().st_ino
for p in proofs:
 assert ref(p['proof']['path'])==p['proof']
 for b in p['screenshots']:assert ref(b['path'])==b
for path,o in owners.items():assert not owner_live(o)
receipt={'status':'pass-completed-browser-byte-identical-hardlinks-all-paths-hashes-and-proofs-preserved','plan':ref(T/'plan-v1.json'),'source':plan['source'],'original_terminal_owners':owners,'operations':len(operations),'bound_screenshot_paths':sum(len(p['screenshots']) for p in proofs),'unchanged_browser_proofs':[p['proof'] for p in proofs],'logical_unique_allocated_reduction_bytes':logical,'free_after':shutil.disk_usage(R).free,'scope':plan['scope']}
with (R/'docs/results/v189-completed-browser-storage-v1.json').open('x') as f:json.dump(receipt,f,indent=2);f.write('\n')
print('PASS',len(operations),'byte-identical paths/',len(owners),'terminal owners/',logical/2**20,'MiB logical unique reduction')
